() => {
  const c = document.getElementById('card');
  const cr = c.getBoundingClientRect();
  const out = [];
  c.querySelectorAll('*').forEach(el=>{
    const r = el.getBoundingClientRect();
    if (r.width===0&&r.height===0) return;
    if (r.left < cr.left-0.5 || r.right > cr.right+0.5 || r.top < cr.top-0.5 || r.bottom > cr.bottom+0.5)
      out.push(el.className+': '+JSON.stringify({l:r.left,t:r.top,r:r.right,b:r.bottom}));
  });
  return {card:[cr.width,cr.height], scroll:[c.scrollWidth,c.scrollHeight], overflow:out};
}

